// 5-touch cadence. The lead's status = the touch that is due now.
// minDays = business days that must pass since the last activity.
// Status values must match your Zoho "Lead Status" picklist exactly.
const STAGES = {
  'Контакт 1 · email':    { step: 1, channel: 'Email',    next: 'Контакт 2 · Telegram', minDays: 0 },
  'Контакт 2 · Telegram': { step: 2, channel: 'Telegram', next: 'Контакт 3 · email',    minDays: 2 },
  'Контакт 3 · email':    { step: 3, channel: 'Email',    next: 'Контакт 4 · WhatsApp', minDays: 3 },
  'Контакт 4 · WhatsApp': { step: 4, channel: 'WhatsApp', next: 'Контакт 5 · фінал',    minDays: 3 },
  'Контакт 5 · фінал':    { step: 5, channel: 'Email',    next: 'Пауза',                minDays: 3 },
};
// Zoho CRM web UI domain: crm.zoho.com, crm.zoho.eu, ...
const ZOHO_UI = 'https://crm.zoho.com';

function businessDaysSince(iso) {
  if (!iso) return 999;
  const start = new Date(iso);
  if (isNaN(start)) return 999;
  let days = 0;
  const d = new Date(start); d.setHours(0, 0, 0, 0);
  const end = new Date(); end.setHours(0, 0, 0, 0);
  while (d < end) {
    d.setDate(d.getDate() + 1);
    const wd = d.getDay();
    if (wd !== 0 && wd !== 6) days++;
  }
  return days;
}

const leads = $input.first()?.json?.data || [];
const out = [];
for (const l of leads) {
  const status = String(l.Lead_Status || '').trim();
  const st = STAGES[status];
  if (!st) continue;
  const last = l.Last_Activity_Time || l.Modified_Time || l.Created_Time;
  const waited = businessDaysSince(last);
  if (waited < st.minDays) continue;
  // score_AI and bant_qulif are custom fields filled by the lead-qualification workflow; empty score = Warm
  const score = (l.score_AI === null || l.score_AI === undefined || l.score_AI === '') ? NaN : Number(l.score_AI);
  const temp = Number.isFinite(score) ? (score >= 71 ? 'Hot' : score >= 31 ? 'Warm' : 'Cold') : 'Warm';
  out.push({ json: {
    lead_id: l.id,
    name: l.Full_Name || [l.First_Name, l.Last_Name].filter(Boolean).join(' '),
    first_name: l.First_Name || '',
    company: l.Company || '',
    description: l.Description || '',
    bant: l.bant_qulif ?? '',
    score: Number.isFinite(score) ? score : null,
    temperature: temp,
    status,
    step: st.step,
    channel: st.channel,
    next_status: st.next,
    business_days_waited: waited === 999 ? null : waited,
    crm_link: ZOHO_UI + '/crm/tab/Leads/' + l.id,
  } });
}
return out;

